/* Implements the generic list pop operation for LPOP/RPOP.
 * The where argument specifies which end of the list is operated on. An
 * optional count may be provided as the third argument of the client's
 * command. */
void popGenericCommand(client *c, int where) {
    int hascount = (c->argc == 3);
    long count = 0;
    robj *value;
    char *event;
    int ql_where;
    int reverse;

    if (where == LIST_HEAD) {
        event = "lpop";
        ql_where = QUICKLIST_HEAD;
        reverse = 0;
    } else {
        event = "rpop";
        ql_where = QUICKLIST_TAIL;
        reverse = 1;
    }

    if (c->argc > 3) {
        addReplyErrorFormat(c,"wrong number of arguments for '%s' command",
                            c->cmd->name);
        return;
    }

    if (hascount) {
        robj *countobj = c->argv[2];
        long long parsed = 0;
        int parse_ok = 0;

        serverAssertWithInfo(NULL, countobj, countobj->type == OBJ_STRING);
        if (sdsEncodedObject(countobj)) {
            const char *p = countobj->ptr;
            size_t slen = sdslen(countobj->ptr);
            size_t plen = 0;
            int negative = 0;
            unsigned long long v = 0;

            if (plen == slen) {
                parse_ok = 0;
            } else {
                if (slen == 1 && p[0] == '0') {
                    parsed = 0;
                    parse_ok = 1;
                } else {
                    if (p[0] == '-') {
                        negative = 1;
                        p++;
                        plen++;
                    }
                    if (negative && plen == slen) {
                        parse_ok = 0;
                    } else if (p[0] >= '1' && p[0] <= '9') {
                        v = p[0] - '0';
                        p++;
                        plen++;
                        while (plen < slen && p[0] >= '0' && p[0] <= '9') {
                            if (v > (ULLONG_MAX / 10)) {
                                parse_ok = 0;
                                break;
                            } else {
                                v *= 10;
                                if (v > (ULLONG_MAX - (unsigned long long)(p[0] - '0'))) {
                                    parse_ok = 0;
                                    break;
                                } else {
                                    v += p[0] - '0';
                                    p++;
                                    plen++;
                                }
                            }
                        }
                        if (plen < slen) {
                            parse_ok = 0;
                        } else if (negative) {
                            if (v > ((unsigned long long)(-(LLONG_MIN+1))+1)) {
                                parse_ok = 0;
                            } else {
                                parsed = -v;
                                parse_ok = 1;
                            }
                        } else {
                            if (v > (unsigned long long)LLONG_MAX) {
                                parse_ok = 0;
                            } else {
                                parsed = v;
                                parse_ok = 1;
                            }
                        }
                    } else {
                        parse_ok = 0;
                    }
                }
            }
        } else if (countobj->encoding == OBJ_ENCODING_INT) {
            parsed = (long)countobj->ptr;
            parse_ok = 1;
        } else {
            serverPanic("Unknown string encoding");
        }

        if (!parse_ok) {
            addReplyError(c,"value is out of range, must be positive");
            return;
        }
        if (parsed < LONG_MIN || parsed > LONG_MAX) {
            addReplyError(c,"value is out of range, must be positive");
            return;
        }
        if (parsed < 0) {
            addReplyError(c,"value is out of range, must be positive");
            return;
        }
        count = (long)parsed;
    }

    robj *o = lookupKeyWriteOrReply(c, c->argv[1], shared.null[c->resp]);
    if (o == NULL) {
        return;
    }
    if (o->type != OBJ_LIST) {
        addReplyErrorObject(c,shared.wrongtypeerr);
        return;
    }

    if (hascount && !count) {
        addReply(c,shared.emptyarray);
        return;
    }

    if (!count) {
        long long vlong = 0;
        value = NULL;
        if (o->encoding == OBJ_ENCODING_QUICKLIST) {
            if (quicklistPopCustom(o->ptr, ql_where, (unsigned char **)&value,
                                   NULL, &vlong, listPopSaver)) {
                if (!value) {
                    if (vlong >= 0 && vlong < OBJ_SHARED_INTEGERS) {
                        incrRefCount(shared.integers[vlong]);
                        value = shared.integers[vlong];
                    } else if (vlong >= LONG_MIN && vlong <= LONG_MAX) {
                        value = createObject(OBJ_STRING, NULL);
                        value->encoding = OBJ_ENCODING_INT;
                        value->ptr = (void*)((long)vlong);
                    } else {
                        value = createObject(OBJ_STRING,sdsfromlonglong(vlong));
                    }
                }
            }
            serverAssert(value != NULL);
            {
                size_t bulklen;
                if (sdsEncodedObject(value)) {
                    bulklen = sdslen(value->ptr);
                } else {
                    bulklen = sdigits10((long)value->ptr);
                }
                if (bulklen < OBJ_SHARED_BULKHDR_LEN) {
                    addReply(c,shared.bulkhdr[bulklen]);
                } else {
                    char buf[128];
                    int len;
                    buf[0] = '$';
                    len = ll2string(buf+1,sizeof(buf)-1,bulklen);
                    buf[len+1] = '\r';
                    buf[len+2] = '\n';
                    addReplyProto(c,buf,len+3);
                }
                addReply(c,value);
                addReply(c,shared.crlf);
            }
            decrRefCount(value);

            {
                robj *key = c->argv[1];
                notifyKeyspaceEvent(NOTIFY_LIST, event, key, c->db->id);
                if (quicklistCount(o->ptr) == 0) {
                    dbDelete(c->db, key);
                    notifyKeyspaceEvent(NOTIFY_GENERIC, "del", key, c->db->id);
                }
                touchWatchedKey(c->db, key);
                trackingInvalidateKey(c, key, 1);
                server.dirty += 1;
            }
        } else {
            serverPanic("Unknown list encoding");
        }
    } else {
        long llen;
        long rangelen;
        long rangestart;
        long rangeend;
        long reply_start;
        long reply_end;
        long reply_len;

        if (o->encoding == OBJ_ENCODING_QUICKLIST) {
            llen = quicklistCount(o->ptr);
            if (count > llen) {
                rangelen = llen;
            } else {
                rangelen = count;
            }
            if (reverse) {
                rangestart = -rangelen;
                rangeend = -1;
            } else {
                rangestart = 0;
                rangeend = rangelen - 1;
            }

            reply_start = rangestart;
            reply_end = rangeend;
            if (reply_start < 0) {
                reply_start = llen + reply_start;
            }
            if (reply_end < 0) {
                reply_end = llen + reply_end;
            }
            if (reply_start < 0) {
                reply_start = 0;
            }
            if (reply_start > reply_end || reply_start >= llen) {
                addReply(c,shared.emptyarray);
            } else {
                if (reply_end >= llen) {
                    reply_end = llen - 1;
                }
                reply_len = (reply_end - reply_start) + 1;
                {
                    if (reply_len < OBJ_SHARED_BULKHDR_LEN) {
                        addReply(c,shared.mbulkhdr[reply_len]);
                    } else {
                        char buf[128];
                        int len;
                        buf[0] = '*';
                        len = ll2string(buf+1,sizeof(buf)-1,reply_len);
                        buf[len+1] = '\r';
                        buf[len+2] = '\n';
                        addReplyProto(c,buf,len+3);
                    }
                }
                {
                    int from;
                    unsigned char direction;
                    if (reverse) {
                        from = reply_end;
                        direction = LIST_HEAD;
                    } else {
                        from = reply_start;
                        direction = LIST_TAIL;
                    }
                    listTypeIterator *li = zmalloc(sizeof(listTypeIterator));
                    li->subject = o;
                    li->encoding = o->encoding;
                    li->direction = direction;
                    li->iter = NULL;
                    int iter_direction;
                    if (direction == LIST_HEAD) {
                        iter_direction = AL_START_TAIL;
                    } else {
                        iter_direction = AL_START_HEAD;
                    }
                    li->iter = quicklistGetIteratorAtIdx(li->subject->ptr,
                                                         iter_direction, from);
                    while (reply_len--) {
                        listTypeEntry entry;
                        serverAssert(li->subject->encoding == li->encoding);
                        entry.li = li;
                        serverAssert(quicklistNext(li->iter, &entry.entry));
                        quicklistEntry *qe = &entry.entry;
                        if (qe->value) {
                            addReplyBulkCBuffer(c,qe->value,qe->sz);
                        } else {
                            addReplyBulkLongLong(c,qe->longval);
                        }
                    }
                    quicklistReleaseIterator(li->iter);
                    zfree(li);
                }
            }

            quicklistDelRange(o->ptr, rangestart, rangelen);

            {
                robj *key = c->argv[1];
                notifyKeyspaceEvent(NOTIFY_LIST, event, key, c->db->id);
                if (quicklistCount(o->ptr) == 0) {
                    dbDelete(c->db, key);
                    notifyKeyspaceEvent(NOTIFY_GENERIC, "del", key, c->db->id);
                }
                touchWatchedKey(c->db, key);
                trackingInvalidateKey(c, key, 1);
                server.dirty += rangelen;
            }
        } else {
            serverPanic("Unknown list encoding");
        }
    }
}

void mpopGenericCommand(client *c, robj **keys, int numkeys, int where, long count) {
    int j;
    robj *o;
    robj *key;

    for (j = 0; j < numkeys; j++) {
        key = keys[j];
        o = lookupKeyWrite(c->db, key);

        /* Non-existing key, move to next key. */
        if (o == NULL) continue;

        if (checkType(c, o, OBJ_LIST)) return;

        long llen = listTypeLength(o);
        /* Empty list, move to next key. */
        if (llen == 0) continue;

        /* Pop a range of elements in a nested arrays way. */
        listPopRangeAndReplyWithKey(c, o, key, where, count, NULL);

        /* Replicate it as [LR]POP COUNT. */
        robj *count_obj = createStringObjectFromLongLong((count > llen) ? llen : count);
        rewriteClientCommandVector(c, 3,
                                   (where == LIST_HEAD) ? shared.lpop : shared.rpop,
                                   key, count_obj);
        decrRefCount(count_obj);
        return;
    }

    /* Look like we are not able to pop up any elements. */
    addReplyNullArray(c);
}

